# Initially generated by GitHub Copilot.
"""Load and iterate over MAM-parsed-plus corpus files."""

import glob
import json
from dataclasses import dataclass, field
from typing import Iterator

_PLUS_DIR = "../MAM-parsed/plus"
_PLAIN_DIR = "../MAM-parsed/plain"


@dataclass
class Corpus:
    """All book39 objects from the plus corpus (collected across all book24 JSON files)."""

    book39s: list = field(default_factory=list)


@dataclass
class PlainCorpus:
    """All parsed plain-corpus files (each entry is the full top-level JSON object)."""

    files: list = field(default_factory=list)  # list of top-level dicts


@dataclass
class Context:
    """Everything a verifier may need: the loaded corpus plus the survey artifacts."""

    corpus: Corpus
    corpus_plain: PlainCorpus
    survey: dict  # loaded plus.json from out/MAM-tmpl-survey/
    survey_plain: dict  # loaded plain.json from out/MAM-tmpl-survey/


def load_plus_corpus() -> Corpus:
    """Load every plus/*.json file and collect all book39s.

    Must be called with the repo root as the working directory.
    """
    pattern = f"{_PLUS_DIR}/*.json"
    paths = sorted(glob.glob(pattern))
    assert paths, f"No plus JSON files found matching {pattern!r}"
    book39s = []
    for path in paths:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        book39s.extend(data["book39s"])
    return Corpus(book39s=book39s)


def load_plain_corpus() -> PlainCorpus:
    """Load every plain/*.json file.

    Must be called with the repo root as the working directory.
    """
    pattern = f"{_PLAIN_DIR}/*.json"
    paths = sorted(glob.glob(pattern))
    assert paths, f"No plain JSON files found matching {pattern!r}"
    files = []
    for path in paths:
        with open(path, encoding="utf-8") as fh:
            files.append(json.load(fh))
    return PlainCorpus(files=files)


def iter_plain_verses(corpus_plain: PlainCorpus) -> Iterator[tuple]:
    """Yield (book39, ch_key, verse_key, verse) for every verse in the plain corpus."""
    for top in corpus_plain.files:
        for book39 in top["book39s"]:
            for ch_key, chapter in book39["chapters"].items():
                for v_key, verse in chapter.items():
                    yield book39, ch_key, v_key, verse


def iter_plain_book39s(corpus_plain: PlainCorpus) -> Iterator[dict]:
    """Yield every book39 dict across all plain corpus files."""
    for top in corpus_plain.files:
        yield from top["book39s"]


def iter_plain_chapters(corpus_plain: PlainCorpus) -> Iterator[tuple]:
    """Yield (book39, ch_key, chapter_dict) for every chapter in the plain corpus."""
    for book39 in iter_plain_book39s(corpus_plain):
        for ch_key, chapter in book39["chapters"].items():
            yield book39, ch_key, chapter


def iter_plain_col_objects(node) -> Iterator[dict]:
    """Yield every plain-column dict node (stmpl, custom_tag, etc.) in node."""
    if isinstance(node, dict):
        yield node
    elif isinstance(node, list):
        for item in node:
            yield from iter_plain_col_objects(item)


def iter_chapters(corpus: Corpus) -> Iterator[tuple]:
    """Yield (book39, chapter_key, chapter_dict) for every chapter."""
    for book39 in corpus.book39s:
        for ch_key, chapter in book39["chapters"].items():
            yield book39, ch_key, chapter


def iter_verses(corpus: Corpus) -> Iterator[tuple]:
    """Yield (book39, ch_key, verse_key, verse) for every verse."""
    for book39, ch_key, chapter in iter_chapters(corpus):
        for v_key, verse in chapter.items():
            yield book39, ch_key, v_key, verse


def iter_template_objects(node) -> Iterator[dict]:
    """Recursively yield every template object (dict with 'tmpl_name') in node.

    Handles the full range of node types found in the plus corpus:
    - dict with 'tmpl_name': a template object; yield it, recurse into tmpl_params values.
    - list: recurse into each element.
    - str: no templates inside; stop.
    """
    if isinstance(node, dict):
        if "tmpl_name" in node:
            yield node
            for val in node.get("tmpl_params", {}).values():
                yield from iter_template_objects(val)
    elif isinstance(node, list):
        for item in node:
            yield from iter_template_objects(item)


def iter_all_template_objects(corpus: Corpus) -> Iterator[dict]:
    """Yield every template object across the entire plus corpus."""
    for _book39, _ch_key, _v_key, verse in iter_verses(corpus):
        for col in verse:
            yield from iter_template_objects(col)
